}

export default function StatCard({
  label,
  value,
  delta,
  deltaSuffix = "%",
  icon = "stats-chart",
  tint = "#F04E3E",
}: StatCardProps) {
  const up = (delta ?? 0) >= 0;

  return (
    <View
      className="flex-1 rounded-2xl bg-white p-4"
